#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing H2H table assembler..."
decode "scripts/ntc_h2h_table.py" << 'B64EOF'

B64EOF
echo "Installed. Run:"
echo "  python scripts/ntc_h2h_table.py --h2h experiments/ntc/h2h_math500_Qwen3-4B.json --h2h experiments/ntc/h2h_math500_Qwen3-8B.json --h2h experiments/ntc/h2h_gpqa_Qwen3-4B.json --h2h experiments/ntc/h2h_gpqa_Qwen3-8B.json --h2h experiments/ntc/h2h_aime24_Qwen3-4B.json --h2h experiments/ntc/h2h_aime24_Qwen3-8B.json"